/bin/bash -lc "node --input-type=module <<'EOF'
import fs from 'node:fs';
import assert from 'node:assert/strict';
const original = fs.readFileSync('src/user.js', 'utf8');
const patch = fs.readFileSync('change.patch', 'utf8');
assert.ok(patch.includes('-  console.log(\"parsing user\");\\n+  console.debug(\"parseUser called\");'));
assert.ok(original.includes('  console.log(\"parsing user\");'));
const candidate = original.replace('  console.log(\"parsing user\");', '  console.debug(\"parseUser called\");');
const { parseUser } = await import('data:text/javascript,' + encodeURIComponent(candidate));
const valid = parseUser(JSON.stringify({ id: 1, name: ' Ada ' }));
assert.deepEqual(valid, { id: 1, name: 'Ada' });
let nullError;
try { parseUser(JSON.stringify({ id: 1, name: null })); } catch (error) { nullError = error; }
assert.equal(nullError?.name, 'TypeError');
console.log(JSON.stringify({ valid, nullError: nullError.message }));
EOF"

